mapper.select:
SELECT * FROM version_package WHERE project_id = #{projectId}
ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT v.* FROM version_package v JOIN project_info p ON p.id = v.project_id
WHERE p.tenant_id = #{tenantId}

    AND v.project_id IN #{projectId}

ORDER BY v.create_time DESC LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT COUNT(*) FROM version_package v JOIN project_info p ON p.id = v.project_id
WHERE p.tenant_id = #{tenantId}

    AND v.project_id IN #{projectId}

SELECT * FROM version_package
WHERE project_id = #{projectId}
ORDER BY create_time DESC
OFFSET #{keepCount}

SELECT * FROM version_package
WHERE project_id = #{projectId} AND version = #{version}
LIMIT 1
